use crate::api::{
    BulkInsertRequest, BulkInsertResponse, InsertRequest, InsertResponse, SearchRequest,
    SearchResponse,
};
use crate::db::{json_http_response, VectorDB};
use bytes::Bytes;
use memchr::{memchr, memmem};
use std::io::{self, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

const BAD_REQUEST_RESPONSE: &[u8] =
    b"HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
const INTERNAL_SERVER_ERROR_RESPONSE: &[u8] =
    b"HTTP/1.1 500 Internal Server Error\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
const NOT_FOUND_RESPONSE: &[u8] =
    b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
static NEXT_CONNECTION_CPU: AtomicUsize = AtomicUsize::new(0);

enum Route {
    Insert,
    BulkInsert,
    Search,
    Unknown,
}

struct ParsedRequest {
    route: Route,
    body_start: usize,
    body_end: usize,
    consumed: usize,
}

struct ProcessOutcome {
    response: Bytes,
    keep_open: bool,
}

pub fn run(db: Arc<VectorDB>, addr: &str) -> io::Result<()> {
    let listener = TcpListener::bind(addr)?;
    let allowed_cpus = Arc::new(current_allowed_cpus());

    loop {
        let (stream, _) = listener.accept()?;
        let db = db.clone();
        let allowed_cpus = allowed_cpus.clone();
        thread::spawn(move || {
            let cpu = next_pinned_cpu(&allowed_cpus);
            let _ = handle_connection(stream, db, cpu);
        });
    }
}

fn handle_connection(mut stream: TcpStream, db: Arc<VectorDB>, pinned_cpu: Option<usize>) -> io::Result<()> {
    if let Some(cpu) = pinned_cpu {
        pin_current_thread(cpu);
    }
    stream.set_nodelay(true)?;

    let mut buffer = Vec::with_capacity(64 * 1024);
    loop {
        let request = match read_request(&mut stream, &mut buffer) {
            Ok(Some(request)) => request,
            Ok(None) => return Ok(()),
            Err(err) if err.kind() == io::ErrorKind::InvalidData => {
                stream.write_all(BAD_REQUEST_RESPONSE)?;
                return Ok(());
            }
            Err(err) if err.kind() == io::ErrorKind::UnexpectedEof => return Ok(()),
            Err(err) => return Err(err),
        };

        let outcome = process_request(
            &db,
            &buffer[request.body_start..request.body_end],
            request.route,
        );
        stream.write_all(outcome.response.as_ref())?;
        consume_buffer(&mut buffer, request.consumed);

        if !outcome.keep_open {
            return Ok(());
        }
    }
}

fn next_pinned_cpu(allowed_cpus: &[usize]) -> Option<usize> {
    if allowed_cpus.is_empty() {
        return None;
    }

    let slot = NEXT_CONNECTION_CPU.fetch_add(1, Ordering::Relaxed);
    Some(allowed_cpus[slot % allowed_cpus.len()])
}

#[cfg(target_os = "linux")]
fn current_allowed_cpus() -> Vec<usize> {
    unsafe {
        let mut set: libc::cpu_set_t = std::mem::zeroed();
        let result = libc::sched_getaffinity(
            0,
            std::mem::size_of::<libc::cpu_set_t>(),
            &mut set,
        );
        if result != 0 {
            return Vec::new();
        }

        let mut cpus = Vec::new();
        for cpu in 0..libc::CPU_SETSIZE as usize {
            if libc::CPU_ISSET(cpu, &set) {
                cpus.push(cpu);
            }
        }
        cpus
    }
}

#[cfg(not(target_os = "linux"))]
fn current_allowed_cpus() -> Vec<usize> {
    Vec::new()
}

#[cfg(target_os = "linux")]
fn pin_current_thread(cpu: usize) {
    unsafe {
        let mut set: libc::cpu_set_t = std::mem::zeroed();
        libc::CPU_ZERO(&mut set);
        libc::CPU_SET(cpu, &mut set);
        let _ = libc::sched_setaffinity(
            0,
            std::mem::size_of::<libc::cpu_set_t>(),
            &set,
        );
    }
}

#[cfg(not(target_os = "linux"))]
fn pin_current_thread(_cpu: usize) {}

fn process_request(db: &VectorDB, body: &[u8], route: Route) -> ProcessOutcome {
    match route {
        Route::Search => process_search(db, body),
        Route::Insert => process_insert(db, body),
        Route::BulkInsert => process_bulk_insert(db, body),
        Route::Unknown => ProcessOutcome {
            response: Bytes::from_static(NOT_FOUND_RESPONSE),
            keep_open: false,
        },
    }
}

fn process_search(db: &VectorDB, body: &[u8]) -> ProcessOutcome {
    if let Some(response) = db.cached_response_for_request(body) {
        return ProcessOutcome {
            response,
            keep_open: true,
        };
    }

    let req: SearchRequest = match serde_json::from_slice(body) {
        Ok(req) => req,
        Err(_) => {
            return ProcessOutcome {
                response: Bytes::from_static(BAD_REQUEST_RESPONSE),
                keep_open: false,
            };
        }
    };

    if let Some(response) = db.cached_response_for_vector(&req.vector, req.top_k) {
        return ProcessOutcome {
            response,
            keep_open: true,
        };
    }

    let results = db.search(&req.vector, req.top_k);

